# D-FOLD-r3 insertion texts (data only). Each entry: file · anchor (unique substring of ONE line
# of the original) · offset · text. New lines go after the anchored line. Insertions only.
# ONE insertion per anchor (two at one anchor would land in reverse order).
INS = []
def add(file, anchor, text, offset=0, expect=None, id='', table=True):
    INS.append(dict(file=file, anchor=anchor, text=text, offset=offset, expect=expect, id=id, table=table))

